  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Diseño stand up con doble función.","Altura de 70 a 88 cm y capacidad de 113 kg.","Aluminio con alma de hierro, plegable."],"beneficios_en":["Stand-up design with dual function.","Height from 70 to 88 cm and 113 kg capacity.","Aluminium with iron core, foldable."],"valor_es":"Un caminador stand up plegable de aluminio.","valor_en":"A foldable aluminium stand-up walker.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"113 kg."},{"q":"¿En qué colores viene la empuñadura?","a":"PVC en gris y negro."},{"q":"¿Se pliega?","a":"Sí, es plegable."},{"q":"¿Dónde descargo la ficha técnica de Caminador Stand Up Doble Función Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"113 kg."},{"q":"Which colours is the handle available in?","a":"PVC in grey and black."},{"q":"Does it fold?","a":"Yes, it is foldable."},{"q":"Where can I download the Konfort Plus Stand Up Dual Function Walker KP1-816L datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["caminador stand up","caminador doble función aluminio","caminador plegable","caminador Konfort Plus","caminador Colombia","ficha técnica KP1-816L-19"],"seo_keywords_en":["stand-up walker","dual-function aluminium walker","folding walker","Konfort Plus walker","walker Colombia","KP1-816L-19 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCWNXVUGY2NZFVHP7PBJ6B7E44LI?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
